import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { Button, Result } from 'antd'
import Text from 'antd/lib/typography/Text'
import { useEffect, useRef, useState } from 'react'
import { showNotification } from '../../../../../components/ShowNotification'
import LayoutContentStyle from '../../../../../components/utility/layoutContent.style'
import PresetList from '../../components/PresetList'
import { PresetContextProvider } from '../../store/context'
import { usePresetList } from '../../store/state/hooks/usePresetStore'
const PresetListContainer = (props) => {
  const { providerCode } = props
  const { fatalError, setFatalError } = useState(false)
  const { resetError } = useResetError()
  const [{ getPresetListData }, getPresetListRequest] = usePresetList()
  const [{ GET_PRESET_LIST_LOADER }] = useLoaderContextValue()
  const [{ GET_PRESET_LIST_ERROR, getPresetListStatus, getPresetListErrorData }] = useErrorContextValue()
  const retryRef = useRef(0)
  useEffect(() => {
    if (getPresetListStatus === 'success') {
      retryRef.current = 0
      resetError([
        'getPresetListStatus'
      ])
    } else if (GET_PRESET_LIST_ERROR && getPresetListStatus) {
      retryRef.current = retryRef.current + 1
      if (retryRef.current.preset <= 5) {
        showNotification('error', 'Failed to fetch preset list, trying again...')
        resetError([
          'getPresetListStatus'
        ])
        setTimeout(getPresetListRequest, 1000)
      } else {
        setFatalError(true)
      }
    }
  }, [GET_PRESET_LIST_ERROR, getPresetListStatus, resetError,
    getPresetListErrorData, getPresetListRequest, setFatalError])

  useEffect(() => {
    getPresetListRequest()
  }, [getPresetListRequest])

  if (!providerCode && fatalError) {
    return (
      <LayoutContentStyle>
        <Result
          status='500'
          title='Oops!'
          subTitle='Sorry, something went wrong. Try reloading the page, if problem persists come back again later.'
          extra={<Button type='primary' onClick={() => window.location.reload()}>Reload</Button>}
        />
      </LayoutContentStyle>
    )
  }

  if (providerCode) {
    return (
      <LayoutContentStyle>
        {fatalError && <Text type='danger'>Failed to fetch presets</Text>}
        <PresetList loading={GET_PRESET_LIST_LOADER} data={getPresetListData} providerCode={providerCode} />
      </LayoutContentStyle>
    )
  }
  return (
    <LayoutContentStyle>
      <h2>Preset List</h2>
      <PresetList loading={GET_PRESET_LIST_LOADER} data={getPresetListData} />
    </LayoutContentStyle>
  )
}

const WithContextPresetListContainer = (props) => (
  <PresetContextProvider>
    <PresetListContainer {...props} />
  </PresetContextProvider>
)

export default WithContextPresetListContainer
