import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback, useRef } from 'react'
import { usePresetContextValue } from '../../context'
import {
  updatePresetStore, getShortProviderList, getProductList,
  getIndependentPackageList, getPresetList, createPreset,
  getPresetDetails, updatePreset, deletePreset, getEditPresetDetails
} from '../actions'

export const usePresetServiceCall = (actionsCall = () => {}) => {
  const [presetState, dispatch] = usePresetContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const callApiRef = useRef(callApi)
  const request = useCallback(async (payload = {}) => {
    await callApiRef.current(actionsCall({
      ...payload
    }))
  }, [actionsCall])

  return [presetState, request]
}

export const useUpdatePresetStore = () => {
  const [, dispatch] = usePresetContextValue()
  return useCallback((data) => {
    dispatch(updatePresetStore(data))
  }, [dispatch])
}

export const useShortProviderList = () => usePresetServiceCall(getShortProviderList)

export const useProductList = () => usePresetServiceCall(getProductList)

export const usePresetList = () => usePresetServiceCall(getPresetList)

export const useIndependentPackageList = () => usePresetServiceCall(getIndependentPackageList)

export const useCreatePreset = () => usePresetServiceCall(createPreset)

export const usePresetDetails = () => usePresetServiceCall(getPresetDetails)

export const useEditPresetDetails = () => usePresetServiceCall(getEditPresetDetails)

export const useUpdatePreset = () => usePresetServiceCall(updatePreset)

export const useDeletePreset = () => usePresetServiceCall(deletePreset)
