import {
  getShortProviderListApi,
  getProductListApi,
  getIndependentPackageListApi,
  getPresetListApi,
  createPresetApi,
  presetDetailsApi,
  updatePresetApi,
  deletePresetApi
} from '../../config/urls'

export const PRESET_ACTIONS = {
  GET_SHORT_PROVIDER_LIST: 'GET_SHORT_PROVIDER_LIST',
  GET_SHORT_PROVIDER_LIST_REQUEST: 'GET_SHORT_PROVIDER_LIST_REQUEST',

  GET_PRODUCT_LIST: 'GET_PRODUCT_LIST',
  GET_PRODUCT_LIST_REQUEST: 'GET_PRODUCT_LIST_REQUEST',

  GET_INDEPENDENT_PACKAGE_LIST: 'GET_INDEPENDENT_PACKAGE_LIST',
  GET_INDEPENDENT_PACKAGE_LIST_REQUEST: 'GET_INDEPENDENT_PACKAGE_LIST_REQUEST',

  GET_PRESET_LIST: 'GET_PRESET_LIST',
  GET_PRESET_LIST_REQUEST: 'GET_PRESET_LIST_REQUEST',

  GET_PRESET_DETAILS: 'GET_PRESET_DETAILS',
  GET_PRESET_DETAILS_REQUEST: 'GET_PRESET_DETAILS',

  GET_EDIT_PRESET_DETAILS: 'GET_EDIT_PRESET_DETAILS',
  GET_EDIT_PRESET_DETAILS_REQUEST: 'GET_EDIT_PRESET_DETAILS_REQUEST',

  CREATE_PRESET: 'CREATE_PRESET',
  CREATE_PRESET_REQUEST: 'CREATE_PRESET_REQUEST',

  UPDATE_PRESET: 'UPDATE_PRESET',
  UPDATE_PRESET_REQUEST: 'UPDATE_PRESET_REQUEST',

  DELETE_PRESET: 'DELETE_PRESET',
  DELETE_PRESET_REQUEST: 'DELETE_PRESET_REQUEST',

  RESET_PRESET_STORE: 'RESET_PRESET_STORE'
}

export const updatePresetStore = (payload) => ({
  type: PRESET_ACTIONS.RESET_PRESET_STORE,
  payload
})

export const getShortProviderList = () => ({
  type: PRESET_ACTIONS.GET_SHORT_PROVIDER_LIST_REQUEST,
  payload: {
    url: getShortProviderListApi
  }
})

export const getProductList = () => ({
  type: PRESET_ACTIONS.GET_PRODUCT_LIST_REQUEST,
  payload: {
    url: getProductListApi,
    method: 'GET'
  }
})

export const getIndependentPackageList = (payload) => ({
  type: PRESET_ACTIONS.GET_INDEPENDENT_PACKAGE_LIST_REQUEST,
  payload: {
    url: getIndependentPackageListApi(payload?.productCode || ''),
    method: 'GET'
  }
})

export const getPresetList = () => ({
  type: PRESET_ACTIONS.GET_PRESET_LIST_REQUEST,
  payload: {
    url: getPresetListApi,
    method: 'GET'
  }
})

export const createPreset = (payload) => ({
  type: PRESET_ACTIONS.CREATE_PRESET_REQUEST,
  payload: {
    ...payload,
    url: createPresetApi,
    method: 'POST'
  }
})

export const getPresetDetails = (payload) => ({
  type: PRESET_ACTIONS.GET_PRESET_DETAILS_REQUEST,
  payload: {
    url: presetDetailsApi(payload.uuid),
    method: 'GET'
  }
})

export const getEditPresetDetails = (payload) => ({
  type: PRESET_ACTIONS.GET_EDIT_PRESET_DETAILS_REQUEST,
  payload: {
    url: presetDetailsApi(payload.uuid),
    method: 'GET'
  }
})

export const updatePreset = (payload) => ({
  type: PRESET_ACTIONS.UPDATE_PRESET_REQUEST,
  payload: {
    ...payload,
    url: updatePresetApi(payload.uuid),
    method: 'PUT'
  }
})

export const deletePreset = (payload) => ({
  type: PRESET_ACTIONS.DELETE_PRESET_REQUEST,
  payload: {
    method: 'DELETE',
    url: deletePresetApi(payload.uuid)
  }
})
