export function compareStringDescending (a, b) {
  if (a.code < b.code) return 1
  if (a.code > b.code) return -1
  return 0
}

export const getTieringError = (err = {}, val = {}) => {
  let { with_hard_copy: withHardCopy = {}, without_hard_copy: withoutHardCopy = {}, ...newErr } = err
  if (val?.with_hard_copy_type === 'flat') {
    const { tiering, premium_type: premiumType, ...newWithHardCopy } = withHardCopy
    if (Object.keys(newWithHardCopy).length) {
      newErr = {
        ...newErr,
        with_hard_copy: newWithHardCopy
      }
    }
  }
  if (val?.with_hard_copy_type === 'tiering') {
    const { flat, ...newWithHardCopy } = withHardCopy
    if (Object.keys(newWithHardCopy).length) {
      newErr = {
        ...newErr,
        with_hard_copy: newWithHardCopy
      }
    }
  }
  if (val?.without_hard_copy_type === 'flat') {
    const { tiering, premium_type: premiumType, ...newWithoutHardCopy } = withoutHardCopy
    if (Object.keys(newWithoutHardCopy).length) {
      newErr = {
        ...newErr,
        with_hard_copy: newWithoutHardCopy
      }
    }
  }
  if (val?.without_hard_copy_type === 'tiering') {
    const { flat, ...newWithoutHardCopy } = withoutHardCopy
    if (Object.keys(newWithoutHardCopy).length) {
      newErr = {
        ...newErr,
        without_hard_copy: newWithoutHardCopy
      }
    }
  }
  return newErr
}

export const getQueryString = (params) => {
  let queryString = Object.keys(params)
    .filter(key => !!params[key])
    .map(key => key + '=' + params[key]).join('&')
  if (queryString) {
    queryString = `?${queryString}`
  } else {
    queryString = ''
  }
  return queryString
}
